package logicscript.ast.nodes.expr;

import logicbyte.bytecode.OpcodeParamValueTable.BinaryExpressionParamValueTable;
import logicscript.ast.ChunkVisitor;

/**
 * <p>
 * Implementation of a binary (two-) value operation; the operation requires both a left- and right-hand-side nested expression.</p>
 *
 * <p>
 * When generated by the lexer, the top-level BinaryExpression is the right-most term of the expression chunk:<br><br>
 * <code> ( 1 + 2 ) + ( 3 + 4 ) </code> becomes: <code>BinExpr { ParenExpr { BinExpr { 1 + 2 } } + ParenExpr { BinExpr { 3 + 4 } }</code>
 * <br>
 * <code>1 + 2 + 3 + 4</code> becomes: <code>BinExpr { BinExpr { BinExpr { 1 + 2 } + 3 } + 4 }</code> such that when the expression is
 * visited, the left-hand resolution descent method yields the deepest node first.
 * </p>
 *
 * @author Lochie
 */
public class BinaryExpression extends Expression {

    public static enum BinaryOperation {

	BIT_AND, BIT_OR, BIT_XOR, BIT_SHL, BIT_SHR,
	BOOL_AND, BOOL_OR,
	VAL_EQ, VAL_NEQ, VAL_GTEQ, VAL_LTEQ, VAL_GT, VAL_LT,
	NUM_ADD, NUM_SUB, NUM_DIV, NUM_MUL, NUM_MOD, NUM_POW;

	/**
	 * Forward lookup to the assembled parameter value instance; this is such that the AST need not be carried around all the time with
	 * garbage attached.
	 *
	 * @return
	 */
	public BinaryExpressionParamValueTable toAssemblyType() {
	    return BinaryExpressionParamValueTable.valueOf(this.name());
	}

    }

    public BinaryOperation operand;
    public Expression lhs, rhs;

    @Override
    public void visit(ChunkVisitor v) throws Exception {
	v.visitExpression(lhs);
	v.visitExpression(rhs);
    }

}
